mapper.select:
SELECT id as a_id, member_id as a_member_id, endpoint as a_endpoint, http_method as a_http_method, status_code as a_status_code, response_time_ms as a_response_time_ms, ip_address as a_ip_address, user_agent as a_user_agent, request_body as a_request_body FROM api_logs WHERE 1 = 1
AND created_at >= #{startDateTime}
AND created_at <= #{endDateTime}
ORDER BY created_at DESC
